#define _GNU_SOURCE
#include <ctype.h>
#include <dlfcn.h>
#include <string.h>
#include <unistd.h>

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);

static int is_numeric_proc_exe(const char *path) {
  const char prefix[] = "/proc/";
  const char suffix[] = "/exe";
  if (strncmp(path, prefix, sizeof(prefix) - 1) != 0) return 0;
